Specification:
Two workers share a semaphore with one permit. A worker may acquire the permit more than once but must release it as many times before returning. Every interleaving must terminate and both workers must complete. On completion the program must print exactly one line `DONE done=1` and then exit; it must terminate.


Current program:
```rust
use std::sync::mpsc;
use std::thread::ThreadId;

struct Sem {
    state: std::sync::Mutex<SemState>,
    cv: std::sync::Condvar,
}

struct SemState {
    // None means the permit is free.
    owner: Option<ThreadId>,
    // Recursion depth for the current owner.
    count: u32,
}

impl Sem {
    fn new() -> Self {
        Self {
            state: std::sync::Mutex::new(SemState {
                owner: None,
                count: 0,
            }),
            cv: std::sync::Condvar::new(),
        }
    }

    fn acq(&self) {
        let me = std::thread::current().id();
        let mut st = self.state.lock().unwrap();
        // Reentrant acquisition: same thread already owns the permit.
        if st.owner == Some(me) {
            st.count += 1;
            return;
        }
        // Wait until the permit is free.
        while st.owner.is_some() {
            st = self.cv.wait(st).unwrap();
        }
        st.owner = Some(me);
        st.count = 1;
    }

    fn rel(&self) {
        let me = std::thread::current().id();
        let mut st = self.state.lock().unwrap();
        // Only the owner may release.
        if st.owner != Some(me) {
            return;
        }
        st.count -= 1;
        if st.count == 0 {
            st.owner = None;
            self.cv.notify_one();
        }
    }
}

fn main() {
    let (tx, rx) = mpsc::sync_channel::<u32>(0);
    let s = std::sync::Arc::new(Sem::new());
    let s1 = std::sync::Arc::clone(&s);
    let tx1 = tx.clone();
    let w1 = std::thread::spawn(move || {
        s1.acq();
        s1.acq();
        s1.rel();
        s1.rel();
        let _ = tx1;
        let _ = rx;
    });
    let s2 = std::sync::Arc::clone(&s);
    let w2 = std::thread::spawn(move || {
        s2.acq();
        s2.rel();
    });
    w1.join().unwrap();
    w2.join().unwrap();
    println!("DONE done=1");
}

```

Fix any concurrency defect and output the complete corrected Rust program, or if there is none reply exactly NO_ISSUES.

